import pytest

def test_skip_location_with_runxfail(testdir):
    testdir.makepyfile("""
        import pytest
        @pytest.mark.skip
        def test_skip_location():
            assert 0
    """)
    result = testdir.runpytest("-rs", "--runxfail")
    # Expect the skip line to point to the test file, line 3
    result.stdout.fnmatch_lines([
        "*SKIPPED [*] *test_skip_location.py:3: unconditional skip*"
    ])

